# Robust pagination with cache and 404 tolerance
song_cache = {}
page_index = 0
while True:
    page = apis.spotify.show_song_library(access_token=access_token, page_index=page_index)
    if not page:
        break
    for item in page:
        song_id = item.song_id
        if song_id not in song_cache:
            song_cache[song_id] = apis.spotify.show_song(song_id=song_id)
        song = song_cache[song_id]
        if song.release_date is None:
            continue
        if should_remove(song.release_date.year, threshold_year, mode):
            try:
                apis.spotify.remove_song_from_library(access_token=access_token, song_id=song_id)
            except Exception as e:
                if getattr(e, "status_code", None) != 404:
                    raise
    page_index += 1

# Verify removal
remaining = []
page_index = 0
while True:
    page = apis.spotify.show_song_library(access_token=access_token, page_index=page_index)
    if not page:
        break
    remaining.extend(item.song_id for item in page)
    page_index += 1
assert all(not should_remove(apis.spotify.show_song(song_id=sid).release_date.year, threshold_year, mode) for sid in remaining)
